changeSet.sql:
alter table tenant_redaction_policies
    add constraint ck_tenant_redaction_policies_vision
    check (vision_ocr_threshold between 0.50 and 0.99);
alter table document_page_routes
    add constraint ck_document_page_routes_path check (path in ('FAST', 'FAST_SIGNATURE', 'VISION'));
drop index if exists idx_pipeline_jobs_stage_package;
create index idx_pipeline_jobs_stage_package on pipeline_jobs (package_id)
    where stage in ('TEXT', 'FIND', 'VISION', 'REDACT');
drop index if exists ux_pipeline_jobs_identity;
create unique index ux_pipeline_jobs_identity on pipeline_jobs (
    tenant_id, stage, package_id, export_cycle,
    coalesce(case when stage in ('TEXT', 'FIND', 'VISION', 'REDACT') then document_id end,
             '00000000-0000-0000-0000-000000000000'::uuid),
    coalesce(page_from, 0),
    coalesce(destination_id, '00000000-0000-0000-0000-000000000000'::uuid),
    coalesce(item_id, '00000000-0000-0000-0000-000000000000'::uuid));
alter table pipeline_jobs drop constraint ck_pipeline_jobs_stage_document;
alter table pipeline_jobs
    add constraint ck_pipeline_jobs_stage_document
    check (stage not in ('TEXT', 'FIND', 'VISION', 'REDACT') or document_id is not null);
alter table pipeline_jobs drop constraint ck_pipeline_jobs_stage;
alter table pipeline_jobs
    add constraint ck_pipeline_jobs_stage
    check (stage in ('TEXT', 'FIND', 'VISION', 'REDACT', 'EXPORT', 'SPLIT_EXPORT'));
-- A VISION job always names its one page.
alter table pipeline_jobs
    add constraint ck_pipeline_jobs_vision_page
    check (stage <> 'VISION' or (page_from is not null and page_from = page_to));

rollback.sql:
delete from pipeline_jobs where stage = 'VISION';
alter table pipeline_jobs drop constraint if exists ck_pipeline_jobs_vision_page;
drop index if exists idx_pipeline_jobs_stage_package;
create index idx_pipeline_jobs_stage_package on pipeline_jobs (package_id)
    where stage in ('TEXT', 'FIND', 'REDACT');
drop index if exists ux_pipeline_jobs_identity;
create unique index ux_pipeline_jobs_identity on pipeline_jobs (
    tenant_id, stage, package_id, export_cycle,
    coalesce(case when stage in ('TEXT', 'FIND', 'REDACT') then document_id end,
             '00000000-0000-0000-0000-000000000000'::uuid),
    coalesce(page_from, 0),
    coalesce(destination_id, '00000000-0000-0000-0000-000000000000'::uuid),
    coalesce(item_id, '00000000-0000-0000-0000-000000000000'::uuid));
alter table pipeline_jobs drop constraint ck_pipeline_jobs_stage_document;
alter table pipeline_jobs
    add constraint ck_pipeline_jobs_stage_document
    check (stage not in ('TEXT', 'FIND', 'REDACT') or document_id is not null);
alter table pipeline_jobs drop constraint ck_pipeline_jobs_stage;
alter table pipeline_jobs
    add constraint ck_pipeline_jobs_stage
    check (stage in ('TEXT', 'FIND', 'REDACT', 'EXPORT', 'SPLIT_EXPORT'));
alter table tenant_redaction_policies drop constraint if exists ck_tenant_redaction_policies_vision;
-- The kinds this task added have no place in the version before it. Open findings of these kinds
-- must be decided before a rollback: the older version cannot read them, so it fails closed.
delete from tenant_redaction_catalog where kind_key in ('SIGNATURE', 'FACE_PHOTO');
